import openpyxl

wb=openpyxl.load_workbook('/root/output/result.xlsx', data_only=False)
ws=wb['Task']

# spot-check some cells across blocks/columns
checks = ['H12','L17','I20','K31','L40','J47','L50']
for a in checks:
    v=ws[a].value
    print(a, v)

# confirm none of the target ranges are None

def range_addrs(r0,r1,c0,c1):
    out=[]
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            out.append((r,c))
    return out

missing=[]
# Step1 target blocks
for r0,r1 in [(12,17),(19,24),(26,31)]:
    for r,c in range_addrs(r0,r1,8,12):
        v=ws.cell(r,c).value
        if not (isinstance(v,str) and v.startswith('=')):
            missing.append((r,c,v))
# Step2 headroom 35-40
for r,c in range_addrs(35,40,8,12):
    v=ws.cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        missing.append((r,c,v))
# Step2 stats 42-47
for r,c in range_addrs(42,47,8,12):
    v=ws.cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        missing.append((r,c,v))
# Step3 weighted mean 50
for c in range(8,13):
    v=ws.cell(50,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        missing.append((50,c,v))

print('Non-formula-or-missing in targets:', len(missing))
if missing:
    print(missing[:10])
